const utf8 = new TextEncoder();
const b64url = (bytes: Uint8Array) => btoa(String.fromCharCode(...bytes)).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");
const unb64url = (s:string) => Uint8Array.from(atob(s.replace(/-/g,"+").replace(/_/g,"/")+"===".slice((s.length+3)%4)),c=>c.charCodeAt(0));
const safeEqual = (a:string,b:string) => {const x=utf8.encode(a),y=utf8.encode(b);if(x.length!==y.length)return false;let n=0;for(let i=0;i<x.length;i++)n|=x[i]^y[i];return n===0};
const json = (value:unknown,status=200,headers:Record<string,string>={}) => new Response(JSON.stringify(value),{status,headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store",...headers}});
function serviceKey(){const direct=Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");if(direct)return direct;try{return JSON.parse(Deno.env.get("SUPABASE_SECRET_KEYS")||"{}").default}catch{return undefined}}
function config(){const url=Deno.env.get("SUPABASE_URL"),key=serviceKey();if(!url||!key)throw new Error("Le service RH est en cours de configuration.");return{url:url.replace(/\/$/,""),key}}
async function db(path:string,method="GET",value?:unknown){const c=config(),headers:Record<string,string>={apikey:c.key,"Content-Type":"application/json",Prefer:method==="POST"?"return=representation":method==="PATCH"?"return=representation":"count=exact"};if(c.key.startsWith("eyJ"))headers.Authorization=`Bearer ${c.key}`;const r=await fetch(`${c.url}/rest/v1/${path}`,{method,headers,body:value===undefined?undefined:JSON.stringify(value),cache:"no-store"});const raw=await r.text();let data;try{data=raw?JSON.parse(raw):null}catch{data=raw}if(!r.ok)throw Object.assign(new Error(typeof data==="object"?(data.message||data.hint||"Erreur de base de données."):String(data)),{status:r.status});return{data,range:r.headers.get("content-range")}}
const qp=(table:string,p:Record<string,string>)=>`${table}?${new URLSearchParams(p)}`;
function cookie(req:Request){const v=(req.headers.get("cookie")||"").split(";").map(x=>x.trim()).find(x=>x.startsWith(`${COOKIE}=`));return v?decodeURIComponent(v.slice(COOKIE.length+1)):""}
function cookieHeader(value:string,maxAge:number){return`${COOKIE}=${encodeURIComponent(value)}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${maxAge}`}
async function hmac(data:string){const key=await crypto.subtle.importKey("raw",utf8.encode(config().key),{name:"HMAC",hash:"SHA-256"},false,["sign"]);return b64url(new Uint8Array(await crypto.subtle.sign("HMAC",key,utf8.encode(data))))}
async function makeToken(payload:Record<string,unknown>){const h=b64url(utf8.encode(JSON.stringify({alg:"HS256",typ:"JWT"}))),b=b64url(utf8.encode(JSON.stringify(payload))),raw=`${h}.${b}`;return`${raw}.${await hmac(raw)}`}
async function claims(req:Request){const p=cookie(req).split(".");if(p.length!==3)return null;const sig=await hmac(`${p[0]}.${p[1]}`);if(!safeEqual(sig,p[2]))return null;try{const c=JSON.parse(new TextDecoder().decode(unb64url(p[1])));return c.exp>Date.now()/1000?c:null}catch{return null}}
async function hashPassword(password:string,salt=crypto.getRandomValues(new Uint8Array(16)),iterations=310000){const key=await crypto.subtle.importKey("raw",utf8.encode(password),"PBKDF2",false,["deriveBits"]),bits=await crypto.subtle.deriveBits({name:"PBKDF2",hash:"SHA-256",salt,iterations},key,256);return`pbkdf2$${iterations}$${b64url(salt)}$${b64url(new Uint8Array(bits))}`}
async function verifyPassword(password:string,stored:string){const [scheme,n,salt,digest]=stored.split("$");if(scheme!=="pbkdf2"||!n||!salt||!digest)return false;return safeEqual(await hashPassword(password,unb64url(salt),Number(n)),`pbkdf2$${n}$${salt}$${digest}`)}
async function current(req:Request){const c=await claims(req);if(!c?.sub)return null;const {data}=await db(qp("hr_accounts",{select:"employee_id,identifier,role,enabled",employee_id:`eq.${c.sub}`,limit:"1"})),a=data?.[0];return a?.enabled?{employee_id:a.employee_id,identifier:a.identifier,role:a.role}:null}
async function readBody(req:Request){const s=await req.text();if(s.length>7200000)throw Object.assign(new Error("Le fichier dépasse la taille autorisée."),{status:413});try{return JSON.parse(s||"{}") as any}catch{throw Object.assign(new Error("Requête invalide."),{status:400})}}
