async function visibleIDs(u:any){if(u.role==="admin")return null;if(u.role==="employee")return[u.employee_id];const {data}=await db(qp("employees",{select:"id",manager_id:`eq.${u.employee_id}`,status:"neq.inactive",limit:"500"}));return[u.employee_id,...data.map((x:any)=>x.id)]}
async function inScope(u:any,id:string){if(u.role==="admin")return true;if(id===u.employee_id)return true;const ids=await visibleIDs(u);return ids?.includes(id)||false}
function idFilter(ids:string[]|null){return ids===null?{}:{employee_id:`in.(${ids.join(",")})`}}
function parisDate(){return new Intl.DateTimeFormat("en-CA",{timeZone:"Europe/Paris",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date())}
function workdays(a:string,b:string){let n=0;for(let d=new Date(`${a}T12:00:00`),end=new Date(`${b}T12:00:00`);d<=end;d.setDate(d.getDate()+1))if(d.getDay()!==0&&d.getDay()!==6)n++;return n}
